package com.shazwan.idash;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.concurrent.*;
/** Actual Activity/emulator capture with original test wallpapers, not a Canvas UI mockup. */
public class ControlVisualChecks extends Instrumentation {
 LauncherActivity a;String phase;int count;StringBuilder details=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);phase=b==null?"after":b.getString("phase","after");start();}
 void ui(Runnable r){Throwable[] error={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 void check(boolean pass,String why){if(!pass)throw new AssertionError(why);count++;}
 void save(Bitmap bitmap,String name)throws Exception{try(OutputStream out=new FileOutputStream(new File(a.getFilesDir(),name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;Bitmap original=null;GlassBackdrop.Frame prior=null;try{
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));CountDownLatch loaded=new CountDownLatch(1);a.worker.execute(()->a.main.post(loaded::countDown));check(loaded.await(30,TimeUnit.SECONDS),"wallpaper/app discovery barrier");waitForIdleSync();original=a.wallpaperBitmap;prior=IosStyle.backdrop(a).frame;
  int w=a.getResources().getDisplayMetrics().widthPixels,h=a.getResources().getDisplayMetrics().heightPixels;
  for(int palette=0;palette<2;palette++){
   Bitmap wall=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(wall);Paint p=new Paint(3);p.setShader(new LinearGradient(0,0,w,h,palette==0?new int[]{0xff080f20,0xff284d72,0xff102b45}:new int[]{0xffedc5db,0xffa7cbef,0xff6d83ba},null,Shader.TileMode.CLAMP));c.drawPaint(p);p.setShader(new RadialGradient(w*.72f,h*.35f,w*.36f,new int[]{palette==0?0xff375f84:0xfff4a6c8,0x00264570},null,Shader.TileMode.CLAMP));c.drawCircle(w*.72f,h*.35f,w*.36f,p);GlassBackdrop.Frame frost=GlassBackdrop.prepare(wall,1);
   ui(()->{if(a.quickControls!=null)a.quickControls.close();a.wallpaperBitmap=wall;a.updateBackdrop();IosStyle.publishGlass(a,frost);a.controlCenter();});Thread.sleep(1200);waitForIdleSync();String name=phase+"-"+(palette==0?"dark":"colour")+"-"+w+"x"+h+".png";Bitmap shot=getUiAutomation().takeScreenshot();check(shot!=null&&shot.getWidth()==w&&shot.getHeight()==h,"actual screenshot dimensions");save(shot,name);shot.recycle();
   TextView[] texts={a.quickControls.mediaControl.title,a.quickControls.mediaControl.artist,a.quickControls.mediaControl.status};int[] savedInk=new int[texts.length];for(int i=0;i<texts.length;i++)savedInk[i]=texts[i].getCurrentTextColor();ui(()->{for(TextView t:texts)t.setTextColor(Color.TRANSPARENT);});Thread.sleep(250);Bitmap background=getUiAutomation().takeScreenshot();
   for(TextView text:texts){int[] at=new int[2];text.getLocationOnScreen(at);android.text.Layout layout=text.getLayout();int available=text.getHeight()-text.getExtendedPaddingTop()-text.getExtendedPaddingBottom();float dy=text.getExtendedPaddingTop()+Math.max(0,available-layout.getHeight())/2f;float left=at[0]+text.getCompoundPaddingLeft()+layout.getLineLeft(0),top=at[1]+dy,tw=layout.getLineRight(0)-layout.getLineLeft(0),th=layout.getLineBottom(0);double min=100;for(int row=1;row<=3;row++)for(int col=1;col<=3;col++){int x=Math.min(w-1,(int)(left+tw*((col-1)*.4f+.1f))),y=Math.min(h-1,(int)(top+th*((row-1)*.4f+.1f)));int bg=background.getPixel(Math.max(0,x),Math.max(0,y)),fg=savedInk[java.util.Arrays.asList(texts).indexOf(text)];float opacity=text.getAlpha()*Color.alpha(fg)/255f;int effective=Color.rgb(Math.round(Color.red(fg)*opacity+Color.red(bg)*(1-opacity)),Math.round(Color.green(fg)*opacity+Color.green(bg)*(1-opacity)),Math.round(Color.blue(fg)*opacity+Color.blue(bg)*(1-opacity)));double b=Color.luminance(bg),ink=Color.luminance(effective);min=Math.min(min,(Math.max(b,ink)+.05)/(Math.min(b,ink)+.05));}details.append(name).append(" text ").append(text.getText()).append(" sampled min contrast ").append(String.format(java.util.Locale.US,"%.2f",min)).append("\n");if(!"before".equals(phase))check(min>=4.5,"primary media text contrast >=4.5, measured "+min);}
   background.recycle();ui(()->{for(int i=0;i<texts.length;i++)texts[i].setTextColor(savedInk[i]);a.quickControls.close();});
  }
  result.putString("stream","PASS: "+count+" real UI visual checks\n"+details);code=Activity.RESULT_OK;
 }catch(Throwable error){result.putString("stream","FAIL after "+count+": "+error+"\n"+details);}finally{if(a!=null){Bitmap restore=original;GlassBackdrop.Frame frame=prior;ui(()->{if(a.quickControls!=null)a.quickControls.close();a.wallpaperBitmap=restore;a.updateBackdrop();if(frame!=null)IosStyle.publishGlass(a,frame);a.finish();});}}finish(code,result);}
}
